{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Collection_Target_vs_Achievement AS WITH Collection_Level_Target AS ( SELECT UPPER(t.Marketplace) AS Marketplace, UPPER(t.Collection) AS Collection, DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Target_Date, CAST(t.Target AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM maplemonk.Zouk_Collection_Level_Target t CROSS JOIN UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), Daily_Achievements AS ( SELECT UPPER(s.Marketplace) AS Marketplace, UPPER(s.Collection) AS Collection, DATE(s.Order_Date) AS Achievement_Date, SUM(IFNULL(s.Selling_Price, 0)) AS Achievement FROM maplemonk.zouk_secondary_sales_Consolidated s WHERE not(lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') GROUP BY 1,2,3 ), Daily_Spends AS ( SELECT UPPER(Marketplace) AS Marketplace, UPPER(Collection) AS Collection, DATE(Date) AS Spend_Date, SUM(IFNULL(Spend, 0)) AS Spend FROM maplemonk.zouk_secondary_pandl GROUP BY 1, 2, 3 ), Combined_Data AS ( SELECT coalesce(coalesce(dt.Target_Date,da.Achievement_Date),ds.Spend_Date) AS Date, coalesce(coalesce(dt.Marketplace,da.Marketplace),ds.Marketplace) as Marketplace, coalesce(coalesce(dt.Collection,da.Collection),ds.Collection) Collection, dt.Target, dt.days_Remaining, dt.no_of_days, COALESCE(da.Achievement, 0) AS Achievement, COALESCE(ds.Spend, 0) AS Spend FROM Collection_Level_Target dt full outer JOIN Daily_Achievements da ON dt.Marketplace = da.Marketplace AND dt.Collection = da.Collection AND dt.Target_Date = da.Achievement_Date FULL OUTER JOIN Daily_Spends ds ON dt.Marketplace = ds.Marketplace AND dt.Collection = ds.Collection AND dt.Target_Date = ds.Spend_Date ), Final_Data AS ( SELECT cd.Date, cd.Marketplace, cd.Collection, cd.Target, cd.Achievement, cd.Spend, cd.days_Remaining, cd.no_of_days, mm.Final_Marketplace, mm.Marketplace_Segments, mm.Channel, CASE WHEN mm.Marketplace IS NULL THEN \'Missing in Marketplace Mapping\' ELSE \'Found\' END AS Mapping_Status FROM Combined_Data cd LEFT JOIN ( select * from maplemonk.Zouk_New_Marketplace_Mapping qualify row_number() over(partition by lower(marketplace) order by 1) = 1 ) mm ON LOWER(cd.Marketplace) = LOWER(mm.Marketplace) ) SELECT Date, Marketplace, Collection, Target, Achievement, Spend, days_Remaining, no_of_days, Final_Marketplace, Marketplace_Segments, Channel FROM Final_Data ORDER BY Date, Marketplace, Collection;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            